// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 warpTime, address caller, uint256 initialBalance) public {
        vm.assume(caller != address(0));
        vm.assume(warpTime > 0);
        vm.assume(initialBalance >= 10 ether);
        vm.deal(caller, initialBalance);
        vm.roll(blockNumber);
        vm.warp(warpTime);

        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");

        if (ok && blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0, "balance should be zero after transfer");
            assertEq(caller.balance, initialBalance - 10 ether + balanceBefore + 10 ether, "caller should receive full balance");
        } else if (ok) {
            assertEq(address(c).balance, balanceBefore + 10 ether, "balance should increase by 10 ether");
        }
    }
}
